```st
FUNCTION_BLOCK FB
VAR_INPUT
    openBtn   : BOOL;
    closeBtn  : BOOL;
    openLimit : BOOL;
    closeLimit: BOOL;
    obstacle  : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL := FALSE;
    motorDown : BOOL := FALSE;
    errorFlag : BOOL := FALSE;
END_VAR
VAR
    state       : INT := 0;  // 0=IDLE,1=OPENING,2=CLOSING,3=FAULT
    prevOpenBtn : BOOL := FALSE;
    prevCloseBtn: BOOL := FALSE;
END_VAR

// Constants
VAR CONSTANT
    IDLE    : INT := 0;
    OPENING : INT := 1;
    CLOSING : INT := 2;
    FAULT   : INT := 3;
END_VAR

// Edge detection (calculated before state update)
openRising  := openBtn AND NOT prevOpenBtn;
closeRising := closeBtn AND NOT prevCloseBtn;

// Main state machine
CASE state OF
    IDLE:
        motorUp   := FALSE;
        motorDown := FALSE;

        IF openRising AND NOT openLimit THEN
            state := OPENING;
        ELSIF closeRising AND NOT closeLimit THEN
            state := CLOSING;
        END_IF;

    OPENING:
        motorUp   := TRUE;
        motorDown := FALSE;

        IF obstacle THEN
            motorUp   := FALSE;
            errorFlag := TRUE;
            state     := FAULT;
        ELSIF openLimit THEN
            motorUp := FALSE;
            state   := IDLE;
        END_IF;

    CLOSING:
        motorUp   := FALSE;
        motorDown := TRUE;

        IF obstacle THEN
            motorDown := FALSE;
            motorUp   := TRUE;
            state     := OPENING;
        ELSIF closeLimit THEN
            motorDown := FALSE;
            state     := IDLE;
        END_IF;

    FAULT:
        motorUp   := FALSE;
        motorDown := FALSE;

        IF openBtn AND closeBtn THEN
            errorFlag := FALSE;
            state     := IDLE;
        END_IF;
END_CASE;

// Update edge detection history
prevOpenBtn  := openBtn;
prevCloseBtn := closeBtn;
END_FUNCTION_BLOCK
```

